-- Neomatra canonical product dataset V3
-- Requires current Laravel migrations and category taxonomy to be applied first.
-- Generated for MySQL 8.x. Embeddings are intentionally NULL and must be rebuilt after import.
SET NAMES utf8mb4;
START TRANSACTION;
SET @cat_access_point := (SELECT id FROM categories WHERE slug = 'access-point' LIMIT 1);
SET @cat_business_laptop := (SELECT id FROM categories WHERE slug = 'business-laptop' LIMIT 1);
SET @cat_consumer_laptop := (SELECT id FROM categories WHERE slug = 'consumer-laptop' LIMIT 1);
SET @cat_cpu := (SELECT id FROM categories WHERE slug = 'cpu' LIMIT 1);
SET @cat_cpu_cooler := (SELECT id FROM categories WHERE slug = 'cpu-cooler' LIMIT 1);
SET @cat_gaming_laptop := (SELECT id FROM categories WHERE slug = 'gaming-laptop' LIMIT 1);
SET @cat_gpu := (SELECT id FROM categories WHERE slug = 'gpu' LIMIT 1);
SET @cat_hdd := (SELECT id FROM categories WHERE slug = 'hdd' LIMIT 1);
SET @cat_headset := (SELECT id FROM categories WHERE slug = 'headset' LIMIT 1);
SET @cat_keyboard := (SELECT id FROM categories WHERE slug = 'keyboard' LIMIT 1);
SET @cat_keyboard_mouse_combo := (SELECT id FROM categories WHERE slug = 'keyboard-mouse-combo' LIMIT 1);
SET @cat_modem := (SELECT id FROM categories WHERE slug = 'modem' LIMIT 1);
SET @cat_monitor := (SELECT id FROM categories WHERE slug = 'monitor' LIMIT 1);
SET @cat_motherboard := (SELECT id FROM categories WHERE slug = 'motherboard' LIMIT 1);
SET @cat_mouse := (SELECT id FROM categories WHERE slug = 'mouse' LIMIT 1);
SET @cat_network_adapter := (SELECT id FROM categories WHERE slug = 'network-adapter' LIMIT 1);
SET @cat_psu := (SELECT id FROM categories WHERE slug = 'psu' LIMIT 1);
SET @cat_ram := (SELECT id FROM categories WHERE slug = 'ram' LIMIT 1);
SET @cat_router := (SELECT id FROM categories WHERE slug = 'router' LIMIT 1);
SET @cat_smartphone := (SELECT id FROM categories WHERE slug = 'smartphone' LIMIT 1);
