SET @cat_switch := (SELECT id FROM categories WHERE slug = 'switch' LIMIT 1);
SET @cat_webcam := (SELECT id FROM categories WHERE slug = 'webcam' LIMIT 1);

ON DUPLICATE KEY UPDATE
`category_id`=VALUES(`category_id`),
`name`=VALUES(`name`),
`brand`=VALUES(`brand`),
`model`=VALUES(`model`),
`variant`=VALUES(`variant`),
`sku_or_part_number`=VALUES(`sku_or_part_number`),
`attributes`=VALUES(`attributes`),
`spec_source_name`=VALUES(`spec_source_name`),
`spec_source_url`=VALUES(`spec_source_url`),
`spec_source_checked_at`=VALUES(`spec_source_checked_at`),
`embedding`=NULL,
`embedding_hash`=NULL,
`embedding_model`=NULL,
`embedding_dimensions`=NULL,
`embedded_at`=NULL,
`embedding_error`=NULL,
`is_active`=1,
`updated_at`=CURRENT_TIMESTAMP;
COMMIT;

-- Verification
SELECT COUNT(*) AS total_products FROM products;
